-- ============================================================
-- AE Cana — corrige categorizacao das despesas 2026 por
-- centro de custo (substitui a carga anterior).
--
-- O que este script faz:
-- 1. Apaga as despesas carregadas anteriormente a partir do
--    relatorio 'ERP Conag - Contas a Pagar' (identificadas pelo
--    padrao '(doc ' na descricao -- nao mexe em nenhum lancamento
--    manual que voce tenha feito por fora desse relatorio).
-- 2. Cria os 15 centros de custo reais do relatorio (ex: 'Insumos
--    Agricolas', 'Mao de Obra Operacional' etc.), vinculados a
--    Faz. Palhadao, frente 'cana'.
-- 3. Re-insere as mesmas 2245 linhas de despesa, agora com o campo
--    centro_custo_id preenchido corretamente -- antes, tudo (Adubos,
--    Defensivos etc.) tinha caido na categoria genérica 'outro',
--    sem diferenciar 'Insumos Agricolas' de 'Manutencao' etc.
--
-- Total: R$ 2.456.060,49 em 2245 linhas (mesmo total de antes,
-- só a categorização mudou).
-- ============================================================

delete from despesas_cana where descricao like '%(doc %';

with fz as (
  select id from fazendas where nome = 'Faz. Palhadão' limit 1
)
insert into centros_custo (fazenda_id, nome, frente, ativo)
select fz.id, v.nome, 'cana', true
from fz, (values
  ('Insumos Agrícolas'),
  ('Mão de Obra Operacional'),
  ('Serviços Técnicos / Consultoria'),
  ('Energia Elétrica'),
  ('Manutenção de Máquinas e Frota'),
  ('Manutenção de Infraestrutura'),
  ('Seguros'),
  ('Instalações - Administração'),
  ('Veículos - Administração'),
  ('Casa-Sede'),
  ('Tributos e Contribuições'),
  ('Combustíveis'),
  ('Terceirização de Serviços Agropecuários'),
  ('Serviços Profissionais (Segurança/Cartório/Contabilidade)'),
  ('Custas Contratuais')
) as v(nome)
on conflict (fazenda_id, nome) do nothing;

with fz as (
  select id from fazendas where nome = 'Faz. Palhadão' limit 1
)
insert into despesas_cana (fazenda_id, talhao_id, centro_custo_id, data, categoria, descricao, valor)
